165	/// Known private/internal hostnames that should be blocked for SSRF prevention.
166	const BLOCKED_HOSTS: &[&str] = &["localhost", "127.0.0.1", "0.0.0.0", "[::1]"];
167	
168	/// Known cloud metadata IP addresses.
169	const BLOCKED_IPS: &[&str] = &["169.254.169.254", "100.100.100.200"];
170	
171	/// Extract the host from an HTTP/HTTPS URL.
172	fn extract_host(url: &str) -> Option<String> {
173	    // Strip scheme
174	    let without_scheme = url
175	        .strip_prefix("https://")
176	        .or_else(|| url.strip_prefix("http://"))?;
177	    // Take everything before the first '/' or end
178	    let host_port = without_scheme.split('/').next()?;
179	    // Strip port if present
180	    let host = if host_port.starts_with('[') {
181	        // IPv6: [::1]:8080
182	        host_port.split(']').next().map(|h| format!("{}]", h))
183	    } else {
184	        Some(host_port.split(':').next().unwrap_or(host_port).to_string())
185	    };
186	    host
187	}
