100	    /// The selection rules:
101	    /// * `--all` or `--config` override → full merged load (legacy).
102	    /// * Positional `<name>` → that workflow file plus project context.
103	    /// * Otherwise → project config + discovery (names from filename
104	    ///   stems, headers parsed for workflow descriptions).
105	    fn build_view(&self) -> Result<BivvyConfig> {
106	        if self.config_override.is_some() {
107	            return load_config(&self.project_root, self.config_override.as_deref());
108	        }
109	        if self.args.all {
110	            return load_merged_config(&self.project_root);
111	        }
112	
113	        let discovery = Discovery::new(&self.project_root);
114	        let mut cfg = match load_project_config(&self.project_root) {
115	            Ok(c) => c,
116	            Err(BivvyError::ConfigNotFound { .. }) => BivvyConfig::default(),
117	            Err(e) => return Err(e),
118	        };
119	
120	        if let Some(ref name) = self.args.target {
121	            // Detail view for a single workflow file. Project config gives
122	            // step definitions; the workflow file overrides/adds.
123	            let path =
124	                discovery
125	                    .workflow_path(name)
126	                    .ok_or_else(|| BivvyError::ConfigValidationError {
127	                        message: format!(
128	                            "Unknown workflow: {name}. No file found at \
129	                         .bivvy/workflows/{name}.yml"
130	                        ),
131	                    })?;
132	            let file = load_single_workflow_file(&path)?;
133	            let mut workflow = file.workflow.clone();
134	            if workflow.description.is_none() {
135	                workflow.description = file.description.clone();
136	            }
137	            cfg.workflows = HashMap::new();
138	            cfg.workflows.insert(name.clone(), workflow);
139	            for (step_name, step) in file.steps {
140	                cfg.steps.insert(step_name, step);
141	            }
142	            for (var_name, var_def) in file.vars {
143	                cfg.vars.insert(var_name, var_def);
144	            }
145	            return Ok(cfg);
146	        }
147	
148	        // Default: discovery-based summary. Augment project config with
149	        // step files (full parse, cheap) and workflow file headers
150	        // (light parse — no full schema deserialize).
151	        for path in discovery.step_files() {
152	            let stem = match path.file_stem().and_then(|s| s.to_str()) {
153	                Some(s) => s.to_string(),
154	                None => continue,
155	            };
156	            if let Ok(step) = load_single_step_file(&path) {
157	                cfg.steps.insert(stem, step);
158	            }
159	        }
160	
161	        for name in discovery.workflow_names() {
162	            if cfg.workflows.contains_key(&name) {
163	                continue;
164	            }
165	            let header = match discovery.workflow_header(&name) {
166	                Ok(h) => h,
167	                Err(_) => continue,
168	            };
169	            let workflow = crate::config::WorkflowConfig {
170	                description: header.description,
171	                steps: header.step_names,
172	                ..Default::default()
173	            };
174	            cfg.workflows.insert(name, workflow);
175	        }
176	
177	        Ok(cfg)
178	    }
179	}
