255	impl Command for LintCommand {
256	    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
257	        // Create event bus for structured logging
258	        let mut event_bus = crate::logging::EventBus::new();
259	        if let Ok(logger) = crate::logging::EventLogger::new(
260	            crate::logging::default_log_dir(),
261	            &format!("sess_{}_lint", chrono::Utc::now().format("%Y%m%d%H%M%S"),),
262	            crate::logging::RetentionPolicy::default(),
263	        ) {
264	            event_bus.add_consumer(Box::new(logger));
265	        }
266	        let start = std::time::Instant::now();
267	
268	        event_bus.emit(&crate::logging::BivvyEvent::SessionStarted {
269	            command: "lint".to_string(),
270	            args: vec![
271	                format!("--format={}", self.args.format),
272	                if self.args.strict {
273	                    "--strict".to_string()
274	                } else {
275	                    String::new()
276	                },
277	                if self.args.fix {
278	                    "--fix".to_string()
279	                } else {
280	                    String::new()
281	                },
282	            ]
283	            .into_iter()
284	            .filter(|s| !s.is_empty())
285	            .collect(),
286	            version: env!("CARGO_PKG_VERSION").to_string(),
287	            os: Some(std::env::consts::OS.to_string()),
288	            working_directory: Some(self.project_root.display().to_string()),
289	        });
290	
291	        // Check if config exists (skip check when override is provided)
292	        if self.config_override.is_none() {
293	            let paths = ConfigPaths::discover(&self.project_root);
294	            if !paths.has_project_config() {
295	                ui.error("No configuration found. Run 'bivvy init' first.");
296	                event_bus.emit(&crate::logging::BivvyEvent::SessionEnded {
297	                    exit_code: 2,
298	                    duration_ms: start.elapsed().as_millis() as u64,
299	                });
300	                return Ok(CommandResult::failure(2));
301	            }
302	        }
303	
304	        // Resolve which target the user asked to lint.
305	        let target = match self.resolve_target() {
306	            Ok(t) => t,
307	            Err(BivvyError::ConfigValidationError { message }) => {
308	                ui.error(&message);
309	                let discovery = Discovery::new(&self.project_root);
310	                let workflows = discovery.workflow_names();
311	                let steps = discovery.step_file_names();
312	                if !workflows.is_empty() {
313	                    ui.message(&format!("Available workflows: {}", workflows.join(", ")));
314	                }
315	                if !steps.is_empty() {
316	                    ui.message(&format!("Available steps: {}", steps.join(", ")));
317	                }
318	                event_bus.emit(&crate::logging::BivvyEvent::SessionEnded {
319	                    exit_code: 1,
320	                    duration_ms: start.elapsed().as_millis() as u64,
321	                });
322	                return Ok(CommandResult::failure(1));
323	            }
324	            Err(e) => return Err(e),
325	        };
326	
327	        // Build the BivvyConfig view to lint along with the file paths
328	        // we actually consulted (used for raw-YAML deprecation scanning).
329	        let (config, lint_file_paths) = match self.build_target_config(&target) {
330	            Ok(pair) => pair,
331	            Err(BivvyError::ConfigParseError { path, message }) => {
332	                ui.error(&format!("Parse error in {}: {}", path.display(), message));
333	                event_bus.emit(&crate::logging::BivvyEvent::SessionEnded {
334	                    exit_code: 1,
335	                    duration_ms: start.elapsed().as_millis() as u64,
336	                });
337	                return Ok(CommandResult::failure(1));
338	            }
339	            Err(BivvyError::ConfigNotFound { path }) => {
340	                ui.error(&format!("File not found: {}", path.display()));
341	                event_bus.emit(&crate::logging::BivvyEvent::SessionEnded {
342	                    exit_code: 1,
343	                    duration_ms: start.elapsed().as_millis() as u64,
344	                });
345	                return Ok(CommandResult::failure(1));
346	            }
347	            Err(e) => return Err(e),
348	        };
