        let mut config = crate::config::BivvyConfig::default();
        config.settings.environment_profiles.default_environment = Some("production".to_string());
        let resolved = cmd.resolve_environment(&config);

        assert_eq!(resolved.name, "ci");
        assert_eq!(
            resolved.source,
            crate::environment::resolver::EnvironmentSource::Flag
        );
    }

    #[test]
    fn execute_shows_environment_in_header() {
        let config = r#"
app_name: Test Project
steps:
  hello:
    command: echo hello
workflows:
  default:
    steps: [hello]
"#;
        let temp = setup_project(config);
        let args = RunArgs {
            env: Some("staging".to_string()),
            ..Default::default()
        };
        let cmd = RunCommand::new(temp.path(), args);
        let mut ui = MockUI::new();

        cmd.execute(&mut ui).unwrap();

        // Run header rendering is verified in runner::display::workflow tests.
        // Here we only verify the command executes successfully against the
        // staging environment.
    }

    #[test]
    fn execute_with_environment_default_workflow() {
        let config = r#"
app_name: Test Project
settings:
  environments:
    ci:
      default_workflow: quick
steps:
  hello:
    command: echo hello
  fast:
    command: echo fast
workflows:
  default:
    steps: [hello]
  quick:
    steps: [fast]
"#;
        let temp = setup_project(config);
        let args = RunArgs {
            env: Some("ci".to_string()),
            ..Default::default()
        };
        let cmd = RunCommand::new(temp.path(), args);
        let mut ui = MockUI::new();

        let result = cmd.execute(&mut ui).unwrap();

        // Should succeed using the "quick" workflow instead of "default"
        assert!(result.success);
    }

    #[test]
    fn execute_explicit_workflow_overrides_env_default() {
        let config = r#"
app_name: Test Project
settings:
  environments:
    ci:
      default_workflow: quick
steps:
  hello:
    command: echo hello
  fast:
    command: echo fast
workflows:
  default:
    steps: [hello]
  quick:
    steps: [fast]
  custom:
    steps: [hello]
"#;
        let temp = setup_project(config);
        let args = RunArgs {
            env: Some("ci".to_string()),
            workflow: "custom".to_string(),
            ..Default::default()
        };
        let cmd = RunCommand::new(temp.path(), args);
        let mut ui = MockUI::new();

        let result = cmd.execute(&mut ui).unwrap();

        // Should succeed using "custom" workflow, not "quick"
        assert!(result.success);
    }

    #[test]
    fn resolve_steps_with_environment_applies_overrides() {
        let config_yaml = r#"
app_name: test
steps:
  hello:
    command: echo hello
    environments:
      ci:
        command: echo ci-hello
workflows:
  default:
    steps: [hello]
"#;
        let temp = setup_project(config_yaml);
        let args = RunArgs::default();
        let cmd = RunCommand::new(temp.path(), args);

        let config = load_merged_config(temp.path()).unwrap();

        // Without environment
        let steps = cmd.resolve_steps(&config, None).unwrap();
        assert_eq!(steps.get("hello").unwrap().execution.command, "echo hello");

        // With ci environment
        let steps = cmd.resolve_steps(&config, Some("ci")).unwrap();
        assert_eq!(
            steps.get("hello").unwrap().execution.command,
            "echo ci-hello"
        );
    }

    #[test]
    fn execute_ci_flag_shows_deprecation_warning() {
        let config = r#"
app_name: Test Project
steps:
  hello:
    command: echo hello
workflows:
  default:
    steps: [hello]
"#;
        let temp = setup_project(config);
        let args = RunArgs {
            ci: true,
            ..Default::default()
        };
        let cmd = RunCommand::new(temp.path(), args);
        let mut ui = MockUI::new();

        cmd.execute(&mut ui).unwrap();

        assert!(ui.has_warning("--ci is deprecated"));
        assert!(ui.has_warning("--non-interactive"));
        assert!(ui.has_warning("--env ci"));
    }

    #[test]
    fn execute_without_ci_flag_no_deprecation_warning() {
        let config = r#"
app_name: Test Project
steps:
  hello:
    command: echo hello
workflows:
  default:
    steps: [hello]
"#;
        let temp = setup_project(config);
        let args = RunArgs::default();
        let cmd = RunCommand::new(temp.path(), args);
        let mut ui = MockUI::new();

        cmd.execute(&mut ui).unwrap();

        assert!(!ui.has_warning("--ci is deprecated"));
    }

    #[test]
    fn summary_shows_recovery_detail() {
        let config = r#"
app_name: Test
steps:
  flaky:
    command: "if [ -f /tmp/bivvy_test_flaky ]; then exit 0; else touch /tmp/bivvy_test_flaky && exit 1; fi"
workflows:
  default:
    steps: [flaky]
"#;
        let temp = setup_project(config);
        let args = RunArgs::default();
        let cmd = RunCommand::new(temp.path(), args);
        let mut ui = MockUI::new();
        ui.set_interactive(true);
        ui.set_default_prompt_response("yes");
        ui.set_prompt_response("recovery_flaky", "retry");

        // Clean up marker from any previous test run
        let _ = std::fs::remove_file("/tmp/bivvy_test_flaky");

        let result = cmd.execute(&mut ui).unwrap();
        assert!(result.success);

        // Summary content is verified in runner::display::workflow tests.

        // Clean up
        let _ = std::fs::remove_file("/tmp/bivvy_test_flaky");
    }

    #[test]
    fn summary_shows_aborted_hint() {
        let config = r#"
app_name: Test
steps:
  broken:
    command: "exit 1"
workflows:
  default:
    steps: [broken]
"#;
        let temp = setup_project(config);
        let args = RunArgs::default();
        let cmd = RunCommand::new(temp.path(), args);
        let mut ui = MockUI::new();
        ui.set_interactive(true);
        ui.set_default_prompt_response("yes");
        ui.set_prompt_response("recovery_broken", "abort");

        let result = cmd.execute(&mut ui).unwrap();
        assert!(!result.success);
        assert_eq!(result.exit_code, 1);

        // The aborted hint goes through the workflow display, verified in
        // runner::display::workflow tests.
    }

    #[test]
    fn vars_available_in_step_commands() {
        let config = r#"
app_name: Test
vars:
  greeting: "hello-from-vars"
steps:
  greet:
    command: "echo ${greeting}"
workflows:
  default:
    steps: [greet]
"#;
        let temp = setup_project(config);
        let args = RunArgs::default();
        let cmd = RunCommand::new(temp.path(), args);
        let mut ui = MockUI::new();

        let result = cmd.execute(&mut ui).unwrap();

        assert!(result.success);
    }

    #[test]
    fn computed_vars_available_in_step_commands() {
        let config = r#"
app_name: Test
vars:
  computed_val:
    command: "echo computed-output"
steps:
  use_var:
    command: "echo ${computed_val}"
workflows:
  default:
    steps: [use_var]
"#;
        let temp = setup_project(config);
        let args = RunArgs::default();
        let cmd = RunCommand::new(temp.path(), args);
        let mut ui = MockUI::new();

        let result = cmd.execute(&mut ui).unwrap();

        assert!(result.success);
    }

    #[test]
    fn execute_unknown_workflow_does_not_duplicate_message() {
        let config = r#"
app_name: test
steps:
  hello:
    command: echo hello
workflows:
  default:
    steps: [hello]
"#;
        let temp = setup_project(config);
        let args = RunArgs {
            workflow: "nonexistent".to_string(),
            ..Default::default()
        };
        let cmd = RunCommand::new(temp.path(), args);
        let mut ui = MockUI::new();

        cmd.execute(&mut ui).unwrap();

        // Command outputs via ui.error() directly
        assert!(ui.has_error("Unknown workflow"));
    }

    #[test]
    fn build_options_diagnostic_funnel_defaults_to_config_value() {
        let temp = TempDir::new().unwrap();
        let args = RunArgs::default();
        let cmd = RunCommand::new(temp.path(), args);

        // Default config has diagnostic_funnel = true
        let config = crate::config::BivvyConfig::default();
        let options = cmd.build_options(&config);
        assert!(options.diagnostic_funnel);

        // Config with diagnostic_funnel = false
        let mut config_off = crate::config::BivvyConfig::default();
        config_off.settings.execution.diagnostic_funnel = false;
        let options = cmd.build_options(&config_off);
        assert!(!options.diagnostic_funnel);
    }

    #[test]
    fn build_options_diagnostic_funnel_cli_flag_overrides_config() {
        let temp = TempDir::new().unwrap();

        // --diagnostic-funnel forces on even when config says false
        let args = RunArgs {
            diagnostic_funnel: true,
            ..Default::default()
        };
        let cmd = RunCommand::new(temp.path(), args);
        let mut config = crate::config::BivvyConfig::default();
        config.settings.execution.diagnostic_funnel = false;
        let options = cmd.build_options(&config);
        assert!(options.diagnostic_funnel);

        // --no-diagnostic-funnel forces off even when config says true
        let args = RunArgs {
            no_diagnostic_funnel: true,
            ..Default::default()
        };
        let cmd = RunCommand::new(temp.path(), args);
        let config = crate::config::BivvyConfig::default();
        let options = cmd.build_options(&config);
        assert!(!options.diagnostic_funnel);
    }

    #[test]
    fn merge_force_directives_no_workflow_uses_cli_only() {
        let args = RunArgs {
            force: vec!["a".to_string()],
            force_all: false,
            ..Default::default()
        };
        let (force, force_all) = merge_force_directives(&args, None);
        assert_eq!(force, ["a".to_string()].into_iter().collect());
        assert!(!force_all);
    }

    #[test]
    fn merge_force_directives_unions_force_lists() {
        let args = RunArgs {
            force: vec!["cli_step".to_string()],
            ..Default::default()
        };
        let workflow = crate::config::WorkflowConfig {
            force: vec!["workflow_step".to_string()],
            ..Default::default()
        };
        let (force, force_all) = merge_force_directives(&args, Some(&workflow));
        assert!(force.contains("cli_step"));
        assert!(force.contains("workflow_step"));
        assert_eq!(force.len(), 2);
        assert!(!force_all);
    }

    #[test]
    fn merge_force_directives_workflow_force_all_propagates() {
        let args = RunArgs {
            force_all: false,
            ..Default::default()
        };
        let workflow = crate::config::WorkflowConfig {
            force_all: true,
            ..Default::default()
        };
        let (_force, force_all) = merge_force_directives(&args, Some(&workflow));
        assert!(force_all);
    }

    #[test]
    fn merge_force_directives_cli_force_all_overrides_workflow_default() {
        let args = RunArgs {
            force_all: true,
            ..Default::default()
        };
        let workflow = crate::config::WorkflowConfig {
            force_all: false,
            ..Default::default()
        };
        let (_force, force_all) = merge_force_directives(&args, Some(&workflow));
        assert!(force_all);
    }

    #[test]
    fn config_diagnostic_funnel_deserialization() {
        let yaml = r#"
app_name: test
settings:
  diagnostic_funnel: false
steps:
  hello:
    command: echo hello
workflows:
  default:
    steps: [hello]
"#;
        let config: crate::config::BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert!(!config.settings.execution.diagnostic_funnel);

        // Omitted means true (default)
        let yaml_default = r#"
app_name: test
steps:
  hello:
    command: echo hello
workflows:
  default:
    steps: [hello]
"#;
        let config: crate::config::BivvyConfig = serde_yaml::from_str(yaml_default).unwrap();
        assert!(config.settings.execution.diagnostic_funnel);
    }
}

