64	impl StatusCommand {
65	    /// Produce JSON output for the status command.
66	    fn execute_json(
67	        &self,
68	        ui: &mut dyn UserInterface,
69	        config: &crate::config::BivvyConfig,
70	        state: &StateStore,
71	        resolved_env: &ResolvedEnvironment,
72	    ) -> Result<CommandResult> {
73	        let app_name = config.app_name.as_deref().unwrap_or("Bivvy Setup");
74	
75	        // Build step statuses
76	        let step_names: Vec<&String> = if let Some(ref step_name) = self.args.step {
77	            if config.steps.contains_key(step_name) {
78	                vec![step_name]
79	            } else {
80	                let err = json!({ "error": format!("Unknown step: {}", step_name) });
81	                ui.message(
82	                    &serde_json::to_string_pretty(&err)
83	                        .map_err(|e| anyhow::anyhow!("JSON serialization failed: {e}"))?,
84	                );
85	                return Ok(CommandResult::failure(1));
86	            }
87	        } else {
88	            config.steps.keys().collect()
89	        };
90	
91	        let steps: Vec<serde_json::Value> = step_names
92	            .iter()
93	            .map(|name| {
94	                let step_config = config.steps.get(*name);
95	                let skipped = step_config
96	                    .map(|s| {
97	                        !s.scoping.only_environments.is_empty()
98	                            && !s
99	                                .scoping
100	                                .only_environments
101	                                .iter()
102	                                .any(|e| e == &resolved_env.name)
103	                    })
104	                    .unwrap_or(false);
105	
106	                if skipped {
107	                    return json!({
108	                        "name": name,
109	                        "status": "skipped",
110	                        "reason": format!("skipped in {}", resolved_env.name),
111	                    });
112	                }
113	
114	                let step_state = state.get_step(name);
115	                let status = step_state.map(|s| s.status).unwrap_or(StepStatus::NeverRun);
116	                let status_str = match status {
117	                    StepStatus::Success => "success",
118	                    StepStatus::Failed => "failed",
119	                    StepStatus::Skipped => "skipped",
120	                    StepStatus::NeverRun => "pending",
121	                };
122	
123	                let mut obj = json!({
124	                    "name": name,
125	                    "status": status_str,
126	                });
127	
128	                if let Some(ss) = step_state {
129	                    if let Some(ts) = ss.last_run {
130	                        obj["last_run"] = json!(ts.to_rfc3339());
131	                    }
132	                    if let Some(ms) = ss.duration_ms {
133	                        obj["duration_ms"] = json!(ms);
134	                    }
135	                }
136	
137	                obj
138	            })
139	            .collect();
140	
141	        // Build requirements
142	        let all_reqs: HashSet<String> = config
143	            .steps
144	            .values()
145	            .flat_map(|s| s.requires.iter().cloned())
146	            .collect();
147	
148	        let requirements: Vec<serde_json::Value> = if !all_reqs.is_empty() {
149	            let probe = EnvironmentProbe::run();
150	            let req_registry = RequirementRegistry::new().with_custom(&config.requirements);
151	            let mut gap_checker = GapChecker::new(&req_registry, &probe, &self.project_root);
152	
153	            let mut sorted_reqs: Vec<&str> = all_reqs.iter().map(|s| s.as_str()).collect();
154	            sorted_reqs.sort();
155	
156	            sorted_reqs
157	                .iter()
158	                .map(|req_name| {
159	                    let status = gap_checker.check_one(req_name);
160	                    let (status_str, detail) = json_requirement_status(&status);
161	                    let mut obj = json!({
162	                        "name": req_name,
163	                        "status": status_str,
164	                    });
165	                    if let Some(d) = detail {
166	                        obj["detail"] = json!(d);
167	                    }
168	                    obj
169	                })
170	                .collect()
171	        } else {
172	            Vec::new()
173	        };
174	
175	        // Assemble top-level JSON
176	        let mut output = json!({
177	            "app_name": app_name,
178	            "environment": {
179	                "name": resolved_env.name,
180	                "source": resolved_env.source.to_string(),
181	            },
182	            "steps": steps,
183	        });
184	
185	        if !requirements.is_empty() {
186	            output["requirements"] = json!(requirements);
187	        }
188	
189	        let json_str = serde_json::to_string_pretty(&output)
190	            .map_err(|e| anyhow::anyhow!("JSON serialization failed: {e}"))?;
191	        ui.message(&json_str);
192	
193	        Ok(CommandResult::success())
194	    }
195	}
