197	impl Command for StatusCommand {
198	    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
199	        // Create event bus for structured logging
200	        let mut event_bus = crate::logging::EventBus::new();
201	        if let Ok(logger) = crate::logging::EventLogger::new(
202	            crate::logging::default_log_dir(),
203	            &format!("sess_{}_status", chrono::Utc::now().format("%Y%m%d%H%M%S"),),
204	            crate::logging::RetentionPolicy::default(),
205	        ) {
206	            event_bus.add_consumer(Box::new(logger));
207	        }
208	        let start = std::time::Instant::now();
209	
210	        event_bus.emit(&crate::logging::BivvyEvent::SessionStarted {
211	            command: "status".to_string(),
212	            args: vec![],
213	            version: env!("CARGO_PKG_VERSION").to_string(),
214	            os: Some(std::env::consts::OS.to_string()),
215	            working_directory: Some(self.project_root.display().to_string()),
216	        });
217	
218	        // Load configuration. With an explicit workflow, we use the
219	        // run-style loader so workflow-bundled steps are visible. Otherwise
220	        // the cheap project-only loader is enough for a status overview.
221	        let config = if let Some(ref override_path) = self.config_override {
222	            match load_config(&self.project_root, Some(override_path)) {
223	                Ok(c) => c,
224	                Err(BivvyError::ConfigNotFound { .. }) => {
225	                    ui.error("No configuration found. Run 'bivvy init' first.");
226	                    event_bus.emit(&crate::logging::BivvyEvent::SessionEnded {
227	                        exit_code: 2,
228	                        duration_ms: start.elapsed().as_millis() as u64,
229	                    });
230	                    return Ok(CommandResult::failure(2));
231	                }
232	                Err(e) => return Err(e),
233	            }
234	        } else if let Some(ref workflow_name) = self.args.workflow {
235	            match load_for_run(&self.project_root, workflow_name) {
236	                Ok(c) => c,
237	                Err(BivvyError::ConfigNotFound { .. }) => {
238	                    ui.error("No configuration found. Run 'bivvy init' first.");
239	                    event_bus.emit(&crate::logging::BivvyEvent::SessionEnded {
240	                        exit_code: 2,
241	                        duration_ms: start.elapsed().as_millis() as u64,
242	                    });
243	                    return Ok(CommandResult::failure(2));
244	                }
245	                Err(e) => return Err(e),
246	            }
247	        } else {
248	            match load_project_config(&self.project_root) {
249	                Ok(c) => c,
250	                Err(BivvyError::ConfigNotFound { .. }) => {
251	                    ui.error("No configuration found. Run 'bivvy init' first.");
252	                    event_bus.emit(&crate::logging::BivvyEvent::SessionEnded {
253	                        exit_code: 2,
254	                        duration_ms: start.elapsed().as_millis() as u64,
255	                    });
256	                    return Ok(CommandResult::failure(2));
257	                }
258	                Err(e) => return Err(e),
259	            }
260	        };
261	
262	        // Apply config default_output when no CLI flag was explicitly set
263	        if ui.output_mode() == OutputMode::Normal {
264	            ui.set_output_mode(config.settings.defaults.output.into());
265	        }
266	
267	        // Get project identity
268	        let project_id = ProjectId::from_path(&self.project_root)?;
269	
270	        // Load state (baseline migrations not needed for status)
271	        let (state, _) = StateStore::load(&project_id)?;
272	
273	        // Resolve environment
274	        let resolved_env = self.resolve_environment(&config);
275	
276	        // JSON output mode
277	        if self.args.json {
278	            let result = self.execute_json(ui, &config, &state, &resolved_env)?;
279	            event_bus.emit(&crate::logging::BivvyEvent::SessionEnded {
280	                exit_code: result.exit_code,
281	                duration_ms: start.elapsed().as_millis() as u64,
282	            });
283	            return Ok(result);
284	        }
285	
286	        let theme = BivvyTheme::new();
287	
288	        // Show header: ⛺ AppName — Status
289	        let app_name = config.app_name.as_deref().unwrap_or("Bivvy Setup");
290	        ui.message(&format!(
291	            "\n  {} {} {} {}\n",
292	            theme.header.apply_to("⛺"),
293	            theme.highlight.apply_to(app_name),
294	            theme.dim.apply_to("—"),
295	            theme.dim.apply_to("Status"),
296	        ));
297	
298	        // Show environment info
299	        ui.message(&format!(
300	            "  {} {} ({})",
301	            theme.key.apply_to("Environment:"),
302	            theme.highlight.apply_to(&resolved_env.name),
303	            theme.dim.apply_to(resolved_env.source.to_string()),
304	        ));
305	        ui.message("");
306	
307	        // Show last run info by checking step state timestamps
308	        let most_recent_step_run = state.steps.values().filter_map(|s| s.last_run).max();
309	        if let Some(last_ts) = most_recent_step_run {
310	            ui.message(&format!(
311	                "  {} {}",
312	                theme.key.apply_to("Last activity:"),
313	                theme.dim.apply_to(format_relative_time(last_ts)),
314	            ));
315	            ui.message("");
316	        }
317	
318	        // Show step status
319	        ui.message(&format!("  {}", theme.key.apply_to("Steps:")));
320	
321	        let step_names: Vec<&String> = if let Some(ref step_name) = self.args.step {
322	            if config.steps.contains_key(step_name) {
323	                vec![step_name]
324	            } else {
325	                ui.error(&format!("Unknown step: {}", step_name));
326	                event_bus.emit(&crate::logging::BivvyEvent::SessionEnded {
327	                    exit_code: 1,
328	                    duration_ms: start.elapsed().as_millis() as u64,
329	                });
330	                return Ok(CommandResult::failure(1));
331	            }
332	        } else {
333	            config.steps.keys().collect()
334	        };
335	
336	        for step_name in &step_names {
337	            // Check if step is skipped by only_environments
338	            let step_config = config.steps.get(*step_name);
339	            let skipped = step_config
340	                .map(|s| {
341	                    !s.scoping.only_environments.is_empty()
342	                        && !s
343	                            .scoping
344	                            .only_environments
345	                            .iter()
346	                            .any(|e| e == &resolved_env.name)
347	                })
348	                .unwrap_or(false);
349	
350	            if skipped {
351	                ui.message(&format!(
352	                    "    {} {:<20} {}",
353	                    theme.dim.apply_to("⊘"),
354	                    step_name,
355	                    theme
356	                        .dim
357	                        .apply_to(format!("(skipped in {})", resolved_env.name)),
358	                ));
359	                continue;
360	            }
361	
362	            let step_state = state.get_step(step_name);
363	            let status = step_state.map(|s| s.status).unwrap_or(StepStatus::NeverRun);
364	            let kind = StatusKind::from(status);
365	
366	            // Build the right-side info (duration or relative time)
367	            let right_side = step_state
368	                .and_then(|s| {
369	                    if status == StepStatus::NeverRun {
370	                        return None;
371	                    }
372	                    // Show duration if available, otherwise relative timestamp
373	                    if let Some(ms) = s.duration_ms {
374	                        let d = Duration::from_millis(ms);
375	                        Some(
376	                            theme
377	                                .duration
378	                                .apply_to(crate::ui::format_duration(d))
379	                                .to_string(),
380	                        )
381	                    } else {
382	                        s.last_run
383	                            .map(|ts| theme.dim.apply_to(format_relative_time(ts)).to_string())
384	                    }
385	                })
386	                .unwrap_or_default();
387	
388	            ui.message(&format!(
389	                "    {} {:<20} {}",
390	                kind.styled(&theme),
391	                step_name,
392	                right_side,
393	            ));
394	        }
395	
396	        // Show requirements section
397	        let all_reqs: HashSet<String> = config
398	            .steps
399	            .values()
400	            .flat_map(|s| s.requires.iter().cloned())
401	            .collect();
402	
403	        if !all_reqs.is_empty() {
404	            ui.message("");
405	            ui.message(&format!("  {}", theme.key.apply_to("Requirements:")));
406	
407	            let probe = EnvironmentProbe::run();
408	            let req_registry = RequirementRegistry::new().with_custom(&config.requirements);
409	            let mut gap_checker = GapChecker::new(&req_registry, &probe, &self.project_root);
410	
411	            let mut sorted_reqs: Vec<&str> = all_reqs.iter().map(|s| s.as_str()).collect();
412	            sorted_reqs.sort();
413	
414	            for req_name in sorted_reqs {
415	                let status = gap_checker.check_one(req_name);
416	                let (icon, desc) = format_requirement_status(&theme, &status);
417	                ui.message(&format!("    {} {:<20} {}", icon, req_name, desc));
418	            }
419	        }
420	
421	        // Show recommendations
422	        let never_run: Vec<_> = config
423	            .steps
424	            .keys()
425	            .filter(|s| {
426	                state
427	                    .get_step(s)
428	                    .map(|st| st.status == StepStatus::NeverRun)
429	                    .unwrap_or(true)
430	            })
431	            .cloned()
432	            .collect();
433	
434	        let failed: Vec<_> = config
435	            .steps
436	            .keys()
437	            .filter(|s| {
438	                state
439	                    .get_step(s)
440	                    .map(|st| st.status == StepStatus::Failed)
441	                    .unwrap_or(false)
442	            })
443	            .cloned()
444	            .collect();
445	
446	        if !failed.is_empty() {
447	            ui.message("");
448	            ui.show_hint(&hints::after_failed_run(&failed));
449	        } else if !never_run.is_empty() {
450	            ui.message("");
451	            if never_run.len() == config.steps.len() {
452	                ui.show_hint(hints::all_steps_pending());
453	            } else {
454	                ui.show_hint(&hints::some_steps_pending(&never_run));
455	            }
456	        }
457	
458	        event_bus.emit(&crate::logging::BivvyEvent::SessionEnded {
459	            exit_code: 0,
460	            duration_ms: start.elapsed().as_millis() as u64,
461	        });
462	        Ok(CommandResult::success())
463	    }
464	}
