22	/// JSON output for the list command.
23	#[derive(Debug, Serialize)]
24	struct ListJsonOutput {
25	    #[serde(skip_serializing_if = "Option::is_none")]
26	    environment: Option<String>,
27	    #[serde(skip_serializing_if = "Option::is_none")]
28	    steps: Option<Vec<StepJsonEntry>>,
29	    #[serde(skip_serializing_if = "Option::is_none")]
30	    workflows: Option<Vec<WorkflowJsonEntry>>,
31	}
