1	//! Lint command implementation.
2	//!
3	//! The `bivvy lint` command validates configuration files using the lint rule system.
4	
5	use std::collections::HashMap;
6	use std::path::{Path, PathBuf};
7	
8	use crate::cli::args::LintArgs;
9	use crate::config::{
10	    load_config, load_merged_config, load_project_config, load_single_step_file,
11	    load_single_workflow_file, BivvyConfig, ConfigPaths, Discovery,
12	};
13	use crate::error::{BivvyError, Result};
14	use crate::lint::{
15	    CircularRequirementDepRule, Fix, FixEngine, HumanFormatter, InstallTemplateMissingRule,
16	    JsonFormatter, LintDiagnostic, LintFormatter, RuleRegistry, SarifFormatter,
17	    ServiceRequirementWithoutHintRule, Severity, TemplateInputsRule, UndefinedTemplateRule,
18	    UnknownRequirementRule,
19	};
20	use crate::registry::Registry;
21	use crate::requirements::registry::RequirementRegistry;
22	use crate::ui::{OutputMode, UserInterface};
23	
24	use super::dispatcher::{Command, CommandResult};
25	
26	/// What the user asked to lint.
27	enum LintTarget {
28	    /// Bare invocation or `--config`: lint `.bivvy/config.yml` only.
29	    ProjectConfig,
30	    /// `--workflow <name>` or positional that resolved to a workflow file.
31	    WorkflowFile(String),
32	    /// `--step <name>` or positional that resolved to a step file.
33	    StepFile(String),
34	    /// `--all`: full merged config (legacy behavior).
35	    All,
36	}
37	
38	/// The lint command implementation.
39	pub struct LintCommand {
40	    project_root: PathBuf,
41	    args: LintArgs,
42	    config_override: Option<PathBuf>,
43	}
44	
45	impl LintCommand {
46	    /// Create a new lint command.
47	    pub fn new(project_root: &Path, args: LintArgs) -> Self {
48	        Self {
49	            project_root: project_root.to_path_buf(),
50	            args,
51	            config_override: None,
52	        }
53	    }
54	
55	    /// Set an override config path.
56	    pub fn with_config_override(mut self, config_override: Option<PathBuf>) -> Self {
57	        self.config_override = config_override;
58	        self
59	    }
60	
61	    /// Get the project root path.
62	    pub fn project_root(&self) -> &Path {
63	        &self.project_root
64	    }
65	
66	    /// Get the command arguments.
67	    pub fn args(&self) -> &LintArgs {
68	        &self.args
69	    }
70	
71	    /// Run all lint rules and collect diagnostics.
72	    fn run_rules(
73	        &self,
74	        registry: &RuleRegistry,
75	        config: &crate::config::BivvyConfig,
76	    ) -> Vec<LintDiagnostic> {
77	        let mut diagnostics = Vec::new();
78	        for rule in registry.iter() {
79	            diagnostics.extend(rule.check(config));
80	        }
81	        diagnostics
82	    }
83	
84	    /// Resolve which target the user asked to lint.
85	    fn resolve_target(&self) -> Result<LintTarget> {
86	        if self.config_override.is_some() {
87	            // Explicit config file override: lint just that file via load_config.
88	            return Ok(LintTarget::ProjectConfig);
89	        }
90	        if let Some(ref name) = self.args.workflow {
91	            return Ok(LintTarget::WorkflowFile(name.clone()));
92	        }
93	        if let Some(ref name) = self.args.step {
94	            return Ok(LintTarget::StepFile(name.clone()));
95	        }
96	        if self.args.all {
97	            return Ok(LintTarget::All);
98	        }
99	        if self.args.config_only {
100	            return Ok(LintTarget::ProjectConfig);
101	        }
102	        if let Some(ref name) = self.args.target {
103	            let discovery = Discovery::new(&self.project_root);
104	            if discovery.workflow_path(name).is_some() {
105	                if discovery.step_path(name).is_some() {
106	                    // Both exist (rare) — pick workflow but surface a hint.
107	                    return Ok(LintTarget::WorkflowFile(name.clone()));
108	                }
109	                return Ok(LintTarget::WorkflowFile(name.clone()));
110	            }
111	            if discovery.step_path(name).is_some() {
112	                return Ok(LintTarget::StepFile(name.clone()));
113	            }
114	            return Err(BivvyError::ConfigValidationError {
115	                message: format!(
116	                    "Unknown lint target: {name}. No file found at \
117	                     .bivvy/workflows/{name}.yml or .bivvy/steps/{name}.yml"
118	                ),
119	            });
120	        }
121	        Ok(LintTarget::ProjectConfig)
122	    }
123	
124	    /// Build the [`BivvyConfig`] view to lint plus the source paths it draws from.
125	    fn build_target_config(&self, target: &LintTarget) -> Result<(BivvyConfig, Vec<PathBuf>)> {
126	        if let Some(ref override_path) = self.config_override {
127	            // Explicit override: just load that file in isolation.
128	            let cfg = load_config(&self.project_root, Some(override_path))?;
129	            return Ok((cfg, vec![override_path.clone()]));
130	        }
131	
132	        match target {
133	            LintTarget::ProjectConfig => {
134	                let cfg = load_project_config(&self.project_root)?;
135	                let path = self.project_root.join(".bivvy").join("config.yml");
136	                Ok((cfg, vec![path]))
137	            }
138	            LintTarget::WorkflowFile(name) => {
139	                let discovery = Discovery::new(&self.project_root);
140	                let workflow_path =
141	                    discovery
142	                        .workflow_path(name)
143	                        .ok_or_else(|| BivvyError::ConfigNotFound {
144	                            path: self
145	                                .project_root
146	                                .join(".bivvy")
147	                                .join("workflows")
148	                                .join(format!("{name}.yml")),
149	                        })?;
150	
151	                // Project file gives us context (settings, templates, custom
152	                // requirements). Missing project file is fine — fall back to
153	                // a default config so we can still lint the workflow file.
154	                let mut cfg = match load_project_config(&self.project_root) {
155	                    Ok(c) => c,
156	                    Err(BivvyError::ConfigNotFound { .. }) => BivvyConfig::default(),
157	                    Err(e) => return Err(e),
158	                };
159	
160	                let workflow_file = load_single_workflow_file(&workflow_path)?;
161	
162	                // Replace workflows with just the named one so cross-workflow
163	                // rules don't fire on workflows we aren't targeting.
164	                let mut workflow = workflow_file.workflow.clone();
165	                if workflow.description.is_none() {
166	                    workflow.description = workflow_file.description.clone();
167	                }
168	                cfg.workflows = HashMap::new();
169	                cfg.workflows.insert(name.clone(), workflow);
170	
171	                // Splice in steps and vars from the workflow file.
172	                for (step_name, step_config) in workflow_file.steps {
173	                    cfg.steps.insert(step_name, step_config);
174	                }
175	                for (var_name, var_def) in workflow_file.vars {
176	                    cfg.vars.insert(var_name, var_def);
177	                }
178	                cfg.migrate_deprecated_fields();
179	
180	                let mut paths = vec![workflow_path];
181	                let project_path = self.project_root.join(".bivvy").join("config.yml");
182	                if project_path.exists() {
183	                    paths.push(project_path);
184	                }
185	                Ok((cfg, paths))
186	            }
187	            LintTarget::StepFile(name) => {
188	                let discovery = Discovery::new(&self.project_root);
189	                let step_path =
190	                    discovery
191	                        .step_path(name)
192	                        .ok_or_else(|| BivvyError::ConfigNotFound {
193	                            path: self
194	                                .project_root
195	                                .join(".bivvy")
196	                                .join("steps")
197	                                .join(format!("{name}.yml")),
198	                        })?;
199	
200	                let mut cfg = match load_project_config(&self.project_root) {
201	                    Ok(c) => c,
202	                    Err(BivvyError::ConfigNotFound { .. }) => BivvyConfig::default(),
203	                    Err(e) => return Err(e),
204	                };
205	
206	                let step_config = load_single_step_file(&step_path)?;
207	                cfg.steps.insert(name.clone(), step_config);
208	                cfg.migrate_deprecated_fields();
209	
210	                let mut paths = vec![step_path];
211	                let project_path = self.project_root.join(".bivvy").join("config.yml");
212	                if project_path.exists() {
213	                    paths.push(project_path);
214	                }
215	                Ok((cfg, paths))
216	            }
217	            LintTarget::All => {
218	                let cfg = load_merged_config(&self.project_root)?;
219	                let discovered = ConfigPaths::discover(&self.project_root);
220	                let mut paths: Vec<PathBuf> = discovered
221	                    .all_existing()
222	                    .iter()
223	                    .map(|p| (*p).clone())
224	                    .collect();
225	                paths.extend(discovered.split_steps.iter().cloned());
226	                paths.extend(discovered.split_workflows.iter().cloned());
227	                Ok((cfg, paths))
228	            }
229	        }
230	    }
231	
232	    /// Format diagnostics using the appropriate formatter.
233	    fn format_output(&self, diagnostics: &[LintDiagnostic]) -> String {
234	        let mut output = Vec::new();
235	
236	        match self.args.format.as_str() {
237	            "json" => {
238	                let formatter = JsonFormatter::new();
239	                formatter.format(diagnostics, &mut output).ok();
240	            }
241	            "sarif" => {
242	                let formatter = SarifFormatter::new("bivvy", env!("CARGO_PKG_VERSION"));
243	                formatter.format(diagnostics, &mut output).ok();
244	            }
245	            _ => {
246	                let formatter = HumanFormatter::new(true);
247	                formatter.format(diagnostics, &mut output).ok();
248	            }
249	        }
250	
251	        String::from_utf8(output).unwrap_or_default()
252	    }
253	}
254	
255	impl Command for LintCommand {
256	    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
257	        // Create event bus for structured logging
258	        let mut event_bus = crate::logging::EventBus::new();
259	        if let Ok(logger) = crate::logging::EventLogger::new(
260	            crate::logging::default_log_dir(),
261	            &format!("sess_{}_lint", chrono::Utc::now().format("%Y%m%d%H%M%S"),),
262	            crate::logging::RetentionPolicy::default(),
263	        ) {
264	            event_bus.add_consumer(Box::new(logger));
265	        }
266	        let start = std::time::Instant::now();
267	
268	        event_bus.emit(&crate::logging::BivvyEvent::SessionStarted {
269	            command: "lint".to_string(),
270	            args: vec![
271	                format!("--format={}", self.args.format),
272	                if self.args.strict {
273	                    "--strict".to_string()
274	                } else {
275	                    String::new()
276	                },
277	                if self.args.fix {
278	                    "--fix".to_string()
279	                } else {
280	                    String::new()
281	                },
282	            ]
283	            .into_iter()
284	            .filter(|s| !s.is_empty())
285	            .collect(),
286	            version: env!("CARGO_PKG_VERSION").to_string(),
287	            os: Some(std::env::consts::OS.to_string()),
288	            working_directory: Some(self.project_root.display().to_string()),
289	        });
290	
291	        // Check if config exists (skip check when override is provided)
292	        if self.config_override.is_none() {
293	            let paths = ConfigPaths::discover(&self.project_root);
294	            if !paths.has_project_config() {
295	                ui.error("No configuration found. Run 'bivvy init' first.");
296	                event_bus.emit(&crate::logging::BivvyEvent::SessionEnded {
297	                    exit_code: 2,
298	                    duration_ms: start.elapsed().as_millis() as u64,
299	                });
300	                return Ok(CommandResult::failure(2));
301	            }
302	        }
303	
304	        // Resolve which target the user asked to lint.
305	        let target = match self.resolve_target() {
306	            Ok(t) => t,
307	            Err(BivvyError::ConfigValidationError { message }) => {
308	                ui.error(&message);
309	                let discovery = Discovery::new(&self.project_root);
310	                let workflows = discovery.workflow_names();
311	                let steps = discovery.step_file_names();
312	                if !workflows.is_empty() {
313	                    ui.message(&format!("Available workflows: {}", workflows.join(", ")));
314	                }
315	                if !steps.is_empty() {
316	                    ui.message(&format!("Available steps: {}", steps.join(", ")));
317	                }
318	                event_bus.emit(&crate::logging::BivvyEvent::SessionEnded {
319	                    exit_code: 1,
320	                    duration_ms: start.elapsed().as_millis() as u64,
321	                });
322	                return Ok(CommandResult::failure(1));
323	            }
324	            Err(e) => return Err(e),
325	        };
326	
327	        // Build the BivvyConfig view to lint along with the file paths
328	        // we actually consulted (used for raw-YAML deprecation scanning).
329	        let (config, lint_file_paths) = match self.build_target_config(&target) {
330	            Ok(pair) => pair,
331	            Err(BivvyError::ConfigParseError { path, message }) => {
332	                ui.error(&format!("Parse error in {}: {}", path.display(), message));
333	                event_bus.emit(&crate::logging::BivvyEvent::SessionEnded {
334	                    exit_code: 1,
335	                    duration_ms: start.elapsed().as_millis() as u64,
336	                });
337	                return Ok(CommandResult::failure(1));
338	            }
339	            Err(BivvyError::ConfigNotFound { path }) => {
340	                ui.error(&format!("File not found: {}", path.display()));
341	                event_bus.emit(&crate::logging::BivvyEvent::SessionEnded {
342	                    exit_code: 1,
343	                    duration_ms: start.elapsed().as_millis() as u64,
344	                });
345	                return Ok(CommandResult::failure(1));
346	            }
347	            Err(e) => return Err(e),
348	        };
349	
350	        let mut deprecation_warnings =
351	            crate::lint::rules::deprecated_fields::collect_deprecation_warnings(&config);
352	
353	        // Scan raw YAML for alias-based deprecations (e.g., old field names)
354	        {
355	            let refs: Vec<&std::path::Path> = lint_file_paths.iter().map(|p| p.as_path()).collect();
356	            deprecation_warnings.extend(
357	                crate::lint::rules::deprecated_fields::collect_raw_yaml_deprecation_warnings(&refs),
358	            );
359	        }
360	
361	        // Display deprecation warnings to the user
362	        for warning in &deprecation_warnings {
363	            ui.warning(warning);
364	        }
365	
366	        event_bus.emit(&crate::logging::BivvyEvent::ConfigLoaded {
367	            config_path: self
368	                .config_override
369	                .as_ref()
370	                .map(|p| p.display().to_string())
371	                .unwrap_or_else(|| ".bivvy/config.yml".to_string()),
372	            parse_duration_ms: None,
373	            deprecation_warnings,
374	        });
375	
376	        // Apply config default_output when no CLI flag was explicitly set
377	        if ui.output_mode() == OutputMode::Normal {
378	            ui.set_output_mode(config.settings.defaults.output.into());
379	        }
380	
381	        // Create rule registry with built-in rules
382	        let mut rule_registry = RuleRegistry::with_builtins();
383	
384	        // Add template-related rules if we can load the template registry
385	        let template_registry_result = if config.template_sources.is_empty() {
386	            Registry::new(Some(&self.project_root))
387	        } else {
388	            Registry::with_remote_sources(Some(&self.project_root), &config.template_sources)
389	        };
390	        if let Ok(template_registry) = template_registry_result {
391	            rule_registry.register(Box::new(UndefinedTemplateRule::new(
392	                template_registry.clone(),
393	            )));
394	            rule_registry.register(Box::new(TemplateInputsRule::new(template_registry)));
395	        }
396	
397	        // Add requirement-related rules
398	        // Each rule takes ownership of its own RequirementRegistry instance
399	        let make_req_registry = || RequirementRegistry::new().with_custom(&config.requirements);
400	        rule_registry.register(Box::new(UnknownRequirementRule::new(make_req_registry())));
401	        rule_registry.register(Box::new(CircularRequirementDepRule::new(
402	            make_req_registry(),
403	        )));
404	        rule_registry.register(Box::new(InstallTemplateMissingRule::new(
405	            make_req_registry(),
406	        )));
407	        rule_registry.register(Box::new(ServiceRequirementWithoutHintRule::new(
408	            make_req_registry(),
409	        )));
410	
411	        // Run all lint rules
412	        let mut diagnostics = self.run_rules(&rule_registry, &config);
413	
414	        // Apply fixes if requested
415	        if self.args.fix {
416	            let fixes: Vec<Fix> = diagnostics
417	                .iter()
418	                .filter_map(|d| {
419	                    // Only create fixes for diagnostics that have suggestions and spans
420	                    match (&d.suggestion, &d.span) {
421	                        (Some(suggestion), Some(span)) => Some(Fix {
422	                            file: span.file.clone(),
423	                            start: 0, // Would need actual byte offsets from marked_yaml
424	                            end: 0,
425	                            replacement: suggestion.clone(),
426	                        }),
427	                        _ => None,
428	                    }
429	                })
430	                .collect();
431	
432	            if !fixes.is_empty() {
433	                let engine = FixEngine::new();
434	                let result = engine.apply_fixes(&diagnostics, &fixes);
435	                if result.applied > 0 {
436	                    ui.success(&format!("Applied {} fix(es)", result.applied));
437	                    // Re-run rules after fixes
438	                    diagnostics = self.run_rules(&rule_registry, &config);
439	                }
440	            }
441	        }
442	
443	        // Evaluate checks defined in config and emit CheckEvaluated events
444	        {
445	            let ctx = crate::config::interpolation::InterpolationContext::default();
446	            let mut snapshot_store = crate::snapshots::SnapshotStore::empty();
447	            for (step_name, step_config) in &config.steps {
448	                if let Some(ref check) = step_config.execution.check {
449	                    let mut evaluator = crate::checks::evaluator::CheckEvaluator::new(
450	                        &self.project_root,
451	                        &ctx,
452	                        &mut snapshot_store,
453	                    );
454	                    let result = evaluator.evaluate(check);
455	                    event_bus.emit(&crate::logging::BivvyEvent::CheckEvaluated {
456	                        step: step_name.clone(),
457	                        check_name: check.name().map(|s| s.to_string()),
458	                        check_type: check.type_name().to_string(),
459	                        outcome: result.outcome.as_str().to_string(),
460	                        description: result.description.clone(),
461	                        details: result.details.clone(),
462	                        duration_ms: None,
463	                    });
464	                }
465	            }
466	        }
467	
468	        // Check for errors based on strict mode
469	        let has_errors = diagnostics.iter().any(|d| d.severity == Severity::Error);
470	        let has_warnings = diagnostics.iter().any(|d| d.severity == Severity::Warning);
471	        let should_fail = has_errors || (self.args.strict && has_warnings);
472	
473	        if diagnostics.is_empty() {
474	            if self.args.format == "human" {
475	                ui.success("Configuration is valid!");
476	            } else {
477	                // For JSON/SARIF, still output the formatted result (empty diagnostics)
478	                let output = self.format_output(&diagnostics);
479	                ui.message(&output);
480	            }
481	            event_bus.emit(&crate::logging::BivvyEvent::SessionEnded {
482	                exit_code: 0,
483	                duration_ms: start.elapsed().as_millis() as u64,
484	            });
485	            return Ok(CommandResult::success());
486	        }
487	
488	        // Output diagnostics in the requested format
489	        let output = self.format_output(&diagnostics);
490	
491	        // For human format, we need to write each line
492	        if self.args.format == "human" {
493	            for line in output.lines() {
494	                if line.starts_with("error") {
495	                    ui.error(line);
496	                } else if line.starts_with("warning") {
497	                    ui.warning(line);
498	                } else {
499	                    ui.message(line);
500	                }
501	            }
502	        } else {
503	            // For JSON/SARIF, output as-is
504	            ui.message(&output);
505	        }
506	
507	        let (exit_code, result) = if should_fail {
508	            (1, CommandResult::failure(1))
509	        } else {
510	            (0, CommandResult::success())
511	        };
512	        event_bus.emit(&crate::logging::BivvyEvent::SessionEnded {
513	            exit_code,
514	            duration_ms: start.elapsed().as_millis() as u64,
515	        });
516	        Ok(result)
517	    }
518	}
