use std::collections::BTreeSet;
use std::path::Path;

/// Known field names for the `settings` mapping.
///
/// Collected from [`Settings`](super::Settings) and all its
/// `#[serde(flatten)]` sub-structs.  `Settings` cannot use serde's
/// `deny_unknown_fields` because of `flatten`, so we validate manually.
const KNOWN_SETTINGS_FIELDS: &[&str] = &[
    // Direct field
    "defaults",
    // LoggingSettings
    "logging",
    "log_retention_days",
    "log_retention_mb",
    // ExecutionSettings
    "parallel",
    "max_parallel",
    "history_retention",
    "diagnostic_funnel",
    "auto_update",
    "default_rerun_window",
    // EnvVarSettings
    "env",
    "env_file",
    "secret_env",
    // EnvironmentProfileSettings
    "default_environment",
    "environments",
];

/// Known field names for step config entries.
///
/// Collected from [`StepConfig`](super::StepConfig) and all its
/// `#[serde(flatten)]` sub-structs.  Same `flatten` limitation as `Settings`.
const KNOWN_STEP_FIELDS: &[&str] = &[
    // Direct fields
    "template",
    "inputs",
    "title",
    "description",
    "depends_on",
    "tools",
    "requires", // alias for tools
    "satisfied_when",
    "watches", // deprecated, accepted for compat
    // ExecutionConfig
    "command",
    "check",
    "completed_check", // alias for check
    "checks",
    "precondition",
    "retry",
    "requires_sudo",
    // EnvironmentVarsConfig
    "env",
    "env_file",
    "env_file_optional",
    "required_env",
    // BehaviorConfig
    "skippable",
    "required",
    "confirm",
    "auto_run",
    "prompt_on_rerun",
    "prompt_if_complete", // alias for prompt_on_rerun
    "allow_failure",
    "sensitive",
    "rerun_window",
    "force",
    // HookConfig
    "before",
    "after",
    // StepOutputSettings
    "output",
    "prompts",
    // EnvironmentScopingConfig
    "environments",
    "only_environments",
];

/// Check config files for unrecognized field names that serde silently ignores.
///
/// `Settings` and `StepConfig` use `#[serde(flatten)]`, which prevents serde
/// from rejecting unknown fields at runtime.  This function fills that gap by
/// comparing YAML keys against the known field sets and returning one warning
/// string per unrecognized field.
pub fn check_unknown_fields(paths: &[&Path]) -> Vec<String> {
    let settings_set: BTreeSet<&str> = KNOWN_SETTINGS_FIELDS.iter().copied().collect();
    let step_set: BTreeSet<&str> = KNOWN_STEP_FIELDS.iter().copied().collect();

    let mut warnings = Vec::new();

    for path in paths {
        let content = match std::fs::read_to_string(path) {
            Ok(c) => c,
            Err(_) => continue,
        };

        let value: serde_yaml::Value = match serde_yaml::from_str(&content) {
            Ok(v) => v,
            Err(_) => continue,
        };

        let mapping = match value.as_mapping() {
            Some(m) => m,
            None => continue,
        };

        check_settings_fields(mapping, path, &settings_set, &mut warnings);
        check_step_fields(mapping, path, &step_set, &mut warnings);
    }

    warnings
}

fn check_settings_fields(
    root: &serde_yaml::Mapping,
    path: &Path,
    known: &BTreeSet<&str>,
    warnings: &mut Vec<String>,
) {
    let settings_val = match root.get(serde_yaml::Value::String("settings".into())) {
        Some(v) => v,
        None => return,
    };
    let settings_map = match settings_val.as_mapping() {
        Some(m) => m,
        None => return,
    };

    for key in settings_map.keys() {
        if let Some(key_str) = key.as_str() {
            if !known.contains(key_str) {
                warnings.push(format!(
                    "unknown field `settings.{}` in {} — it will be ignored; \
                     check spelling or see https://bivvy.dev/configuration",
                    key_str,
                    path.display(),
                ));
            }
        }
    }
}

fn check_step_fields(
    root: &serde_yaml::Mapping,
    path: &Path,
    known: &BTreeSet<&str>,
    warnings: &mut Vec<String>,
) {
    let steps_val = match root.get(serde_yaml::Value::String("steps".into())) {
        Some(v) => v,
        None => return,
    };
    let steps_map = match steps_val.as_mapping() {
        Some(m) => m,
        None => return,
    };

    for (step_name, step_val) in steps_map {
        let (Some(name_str), Some(step_map)) = (step_name.as_str(), step_val.as_mapping()) else {
            continue;
        };
        for key in step_map.keys() {
            if let Some(key_str) = key.as_str() {
                if !known.contains(key_str) {
                    warnings.push(format!(
                        "unknown field `steps.{}.{}` in {} — it will be ignored; \
                         check spelling or see https://bivvy.dev/configuration",
                        name_str,
                        key_str,
                        path.display(),
                    ));
                }
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;
    use tempfile::TempDir;

    fn write_config(dir: &TempDir, content: &str) -> std::path::PathBuf {
        let path = dir.path().join("config.yml");
        fs::write(&path, content).unwrap();
        path
    }

    #[test]
    fn no_warnings_for_valid_config() {
        let dir = TempDir::new().unwrap();
        let path = write_config(
            &dir,
            r#"
settings:
  parallel: true
  max_parallel: 8
  defaults:
    output: quiet
steps:
  hello:
    command: echo hello
    depends_on: [world]
"#,
        );
        let warnings = check_unknown_fields(&[path.as_path()]);
        assert!(warnings.is_empty(), "unexpected warnings: {:?}", warnings);
    }

    #[test]
    fn warns_on_unknown_settings_field() {
        let dir = TempDir::new().unwrap();
        let path = write_config(
            &dir,
            r#"
settings:
  parllel: true
"#,
        );
        let warnings = check_unknown_fields(&[path.as_path()]);
        assert_eq!(warnings.len(), 1);
        assert!(warnings[0].contains("settings.parllel"));
    }

    #[test]
    fn warns_on_unknown_step_field() {
        let dir = TempDir::new().unwrap();
        let path = write_config(
            &dir,
            r#"
steps:
  hello:
    comand: echo hello
"#,
        );
        let warnings = check_unknown_fields(&[path.as_path()]);
        assert_eq!(warnings.len(), 1);
        assert!(warnings[0].contains("steps.hello.comand"));
    }

    #[test]
    fn accepts_serde_aliases() {
        let dir = TempDir::new().unwrap();
        let path = write_config(
            &dir,
            r#"
steps:
  deps:
    command: yarn install
    requires:
      - node
    prompt_if_complete: true
    completed_check:
      type: execution
      command: "test -d node_modules"
"#,
        );
        let warnings = check_unknown_fields(&[path.as_path()]);
        assert!(warnings.is_empty(), "unexpected warnings: {:?}", warnings);
    }

    #[test]
    fn multiple_unknown_fields() {
        let dir = TempDir::new().unwrap();
        let path = write_config(
            &dir,
            r#"
settings:
  auto_updte: true
  parllel: false
steps:
  build:
    commnd: make
    retyr: 3
"#,
        );
        let warnings = check_unknown_fields(&[path.as_path()]);
        assert_eq!(warnings.len(), 4);
