        let path = std::path::PathBuf::from("/nonexistent/config.yml");
        let warnings = check_unknown_fields(&[path.as_path()]);
        assert!(warnings.is_empty());
    }

    #[test]
    fn handles_invalid_yaml() {
        let dir = TempDir::new().unwrap();
        let path = write_config(&dir, "invalid: yaml: [");
        let warnings = check_unknown_fields(&[path.as_path()]);
        assert!(warnings.is_empty());
    }

    #[test]
    fn checks_multiple_files() {
        let dir = TempDir::new().unwrap();
        let path1 = dir.path().join("a.yml");
        let path2 = dir.path().join("b.yml");
        fs::write(
            &path1,
            r#"
settings:
  unknown_a: true
"#,
        )
        .unwrap();
        fs::write(
            &path2,
            r#"
steps:
  x:
    unknown_b: foo
"#,
        )
        .unwrap();
